11	DistinctSortedChunkTransform::DistinctSortedChunkTransform(
12	    const Block & header_,
13	    const SizeLimits & output_size_limits_,
14	    UInt64 limit_hint_,
15	    const SortDescription & sorted_columns_descr_,
16	    const Names & source_columns)
17	    : ISimpleTransform(header_, header_, true)
18	    , limit_hint(limit_hint_)
19	    , output_size_limits(output_size_limits_)
20	    , sorted_columns_descr(sorted_columns_descr_)
21	{
22	    /// calculate sorted columns positions
23	    sorted_columns_pos.reserve(sorted_columns_descr.size());
24	    for (auto const & descr : sorted_columns_descr)
25	    {
26	        size_t pos = header_.getPositionByName(descr.column_name);
27	        sorted_columns_pos.emplace_back(pos);
28	    }
29	
30	    /// calculate non-sorted columns positions
31	    other_columns_pos.reserve(source_columns.size());
32	    for (const auto & source_column : source_columns)
33	    {
34	        size_t pos = header_.getPositionByName(source_column);
35	        if (std::find(sorted_columns_pos.begin(), sorted_columns_pos.end(), pos) != sorted_columns_pos.end())
36	            continue;
37	
38	        const auto & col = header_.getByPosition(pos).column;
39	        if (col && !isColumnConst(*col))
40	            other_columns_pos.emplace_back(pos);
41	    }
42	
43	    /// reserve space in auxiliary column vectors for processing
44	    sorted_columns.reserve(sorted_columns_pos.size());
45	    other_columns.reserve(other_columns_pos.size());
46	    current_key.reserve(sorted_columns.size());
47	}
