49	void DistinctSortedChunkTransform::initChunkProcessing(const Columns & input_columns)
50	{
51	    sorted_columns.clear();
52	    for (size_t pos : sorted_columns_pos)
53	        sorted_columns.emplace_back(input_columns[pos].get());
54	
55	    other_columns.clear();
56	    for (size_t pos : other_columns_pos)
57	        other_columns.emplace_back(input_columns[pos].get());
58	
59	    if (!other_columns.empty() && data.type == ClearableSetVariants::Type::EMPTY)
60	        data.init(ClearableSetVariants::chooseMethod(other_columns, other_columns_sizes));
61	}
