63	size_t DistinctSortedChunkTransform::ordinaryDistinctOnRange(IColumn::Filter & filter, size_t range_begin, size_t range_end, bool clear_data)
64	{
65	    size_t count = 0;
66	    switch (data.type)
67	    {
68	        case ClearableSetVariants::Type::EMPTY:
69	            break;
70	            // clang-format off
71	#define M(NAME) \
72	        case ClearableSetVariants::Type::NAME: \
73	            count = buildFilterForRange(*data.NAME, filter, range_begin, range_end, clear_data); \
74	            break;
75	
76	        APPLY_FOR_SET_VARIANTS(M)
77	#undef M
78	            // clang-format on
79	    }
80	    return count;
81	}
