83	template <typename Method>
84	size_t DistinctSortedChunkTransform::buildFilterForRange(
85	    Method & method, IColumn::Filter & filter, size_t range_begin, size_t range_end, bool clear_data)
86	{
87	    typename Method::State state(other_columns, other_columns_sizes, nullptr);
88	    if (clear_data)
89	        method.data.clear();
90	
91	    size_t count = 0;
92	    for (size_t i = range_begin; i < range_end; ++i)
93	    {
94	        auto emplace_result = state.emplaceKey(method.data, i, data.string_pool);
95	
96	        /// emit the record if there is no such key in the current set, skip otherwise
97	        filter[i] = emplace_result.isInserted();
98	        if (filter[i])
99	            ++count;
100	    }
101	    return count;
102	}
