104	void DistinctSortedChunkTransform::setCurrentKey(const size_t row_pos)
105	{
106	    current_key.clear();
107	    for (auto const & col : sorted_columns)
108	    {
109	        current_key.emplace_back(col->cloneEmpty());
110	        current_key.back()->insertFrom(*col, row_pos);
111	    }
112	}
