114	bool DistinctSortedChunkTransform::isCurrentKey(const size_t row_pos) const
115	{
116	    for (size_t i = 0; i < sorted_columns.size(); ++i)
117	    {
118	        int res = current_key[i]->compareAt(0, row_pos, *sorted_columns[i], sorted_columns_descr[i].nulls_direction);
119	        if (res != 0)
120	            return false;
121	    }
122	    return true;
123	}
