11	///
12	/// DISTINCT optimization for sorted chunks
13	///
14	/// (1) distinct columns are split into two groups - sorted i.e. belong to sorting prefix,
15	/// and non-sorted (other columns w/o sorting guarantees).
16	///
17	/// (2) Rows are split into ranges. Range is a set of rows where the sorting prefix value is the same.
18	/// If there are no non-sorted columns, then we just skip all rows in range except one.
19	/// If there are non-sorted columns, then for each range, we use a hash table to find unique rows in a range.
20	///
21	/// (3) The implementation also checks if current chunks is continuation of previous one,
22	/// i.e. sorting prefix value of last row in previous chunk is the same as of first row in current one,
23	/// so it can correctly process sorted stream as well.
24	/// For this, we don't clear sorting prefix value and hash table after a range is processed,
25	/// only right before a new range processing
26	///
27	class DistinctSortedChunkTransform : public ISimpleTransform
28	{
29	public:
30	    DistinctSortedChunkTransform(
31	        const Block & header_,
32	        const SizeLimits & output_size_limits_,
33	        UInt64 limit_hint_,
34	        const SortDescription & sorted_columns_descr_,
35	        const Names & source_columns_);
36	
37	    String getName() const override { return "DistinctSortedChunkTransform"; }
38	
39	protected:
40	    void transform(Chunk & chunk) override;
41	
42	private:
43	    void initChunkProcessing(const Columns & input_columns);
44	    std::pair<size_t, size_t> continueWithPrevRange(size_t chunk_rows, IColumn::Filter & filter);
45	    size_t ordinaryDistinctOnRange(IColumn::Filter & filter, size_t range_begin, size_t range_end, bool clear_data);
46	    inline void setCurrentKey(size_t row_pos);
47	    inline bool isCurrentKey(size_t row_pos) const;
48	    inline size_t getRangeEnd(size_t range_begin, size_t range_end) const;
49	
50	    template <typename Method>
51	    size_t buildFilterForRange(Method & method, IColumn::Filter & filter, size_t range_begin, size_t range_end, bool clear_data);
52	
53	
54	    ClearableSetVariants data;
55	    const size_t limit_hint;
56	    size_t total_output_rows = 0;
57	
58	    /// Restrictions on the maximum size of the output data.
59	    const SizeLimits output_size_limits;
60	
61	    const SortDescription sorted_columns_descr;
62	    ColumnNumbers sorted_columns_pos;
63	    ColumnRawPtrs sorted_columns; // used during processing
64	
65	    ColumnNumbers other_columns_pos;
66	    Sizes other_columns_sizes;
67	    ColumnRawPtrs other_columns; // used during processing
68	
69	    MutableColumns current_key;
70	};
71	
72	}
