13	static bool checkColumnsAlreadyDistinct(const Names & columns, const NameSet & distinct_names)
14	{
15	    if (distinct_names.empty())
16	        return false;
17	
18	    /// Now we need to check that distinct_names is a subset of columns.
19	    std::unordered_set<std::string_view> columns_set(columns.begin(), columns.end());
20	    for (const auto & name : distinct_names)
21	        if (!columns_set.contains(name))
22	            return false;
23	
24	    return true;
25	}
