27	static ITransformingStep::Traits getTraits(bool pre_distinct, bool already_distinct_columns)
28	{
29	    return ITransformingStep::Traits
30	    {
31	        {
32	            .preserves_distinct_columns = already_distinct_columns, /// Will be calculated separately otherwise
33	            .returns_single_stream = !pre_distinct && !already_distinct_columns,
34	            .preserves_number_of_streams = pre_distinct || already_distinct_columns,
35	            .preserves_sorting = true, /// Sorting is preserved indeed because of implementation.
36	        },
37	        {
38	            .preserves_number_of_rows = false,
39	        }
40	    };
41	}
42	
43	static SortDescription getSortDescription(const SortDescription & input_sort_desc, const Names& columns)
44	{
45	    SortDescription distinct_sort_desc;
46	    for (const auto & sort_column_desc : input_sort_desc)
47	    {
48	        if (std::find(begin(columns), end(columns), sort_column_desc.column_name) == columns.end())
49	            break;
50	        distinct_sort_desc.emplace_back(sort_column_desc);
51	    }
52	    return distinct_sort_desc;
53	}
