56	DistinctStep::DistinctStep(
57	    const DataStream & input_stream_,
58	    const SizeLimits & set_size_limits_,
59	    UInt64 limit_hint_,
60	    const Names & columns_,
61	    bool pre_distinct_,
62	    bool optimize_distinct_in_order_)
63	    : ITransformingStep(
64	            input_stream_,
65	            input_stream_.header,
66	            getTraits(pre_distinct_, checkColumnsAlreadyDistinct(columns_, input_stream_.distinct_columns)))
67	    , set_size_limits(set_size_limits_)
68	    , limit_hint(limit_hint_)
69	    , columns(columns_)
70	    , pre_distinct(pre_distinct_)
71	    , optimize_distinct_in_order(optimize_distinct_in_order_)
72	{
73	    if (!output_stream->distinct_columns.empty() /// Columns already distinct, do nothing
74	        && (!pre_distinct /// Main distinct
75	            || input_stream_.has_single_port)) /// pre_distinct for single port works as usual one
76	    {
77	        /// Build distinct set.
78	        for (const auto & name : columns)
79	            output_stream->distinct_columns.insert(name);
80	    }
81	}
