83	void DistinctStep::transformPipeline(QueryPipelineBuilder & pipeline, const BuildQueryPipelineSettings &)
84	{
85	    const auto & input_stream = input_streams.back();
86	    if (checkColumnsAlreadyDistinct(columns, input_stream.distinct_columns))
87	        return;
88	
89	    if (!pre_distinct)
90	        pipeline.resize(1);
91	
92	    if (optimize_distinct_in_order)
93	    {
94	        SortDescription distinct_sort_desc = getSortDescription(input_stream.sort_description, columns);
95	        if (!distinct_sort_desc.empty())
96	        {
97	            /// pre-distinct for sorted chunks
98	            if (pre_distinct)
99	            {
100	                pipeline.addSimpleTransform(
101	                    [&](const Block & header, QueryPipelineBuilder::StreamType stream_type) -> ProcessorPtr
102	                    {
103	                        if (stream_type != QueryPipelineBuilder::StreamType::Main)
104	                            return nullptr;
105	
106	                        return std::make_shared<DistinctSortedChunkTransform>(
107	                            header, set_size_limits, limit_hint, distinct_sort_desc, columns);
108	                    });
109	                return;
110	            }
111	            /// final distinct for sorted stream (sorting inside and among chunks)
112	            if (input_stream.sort_mode == DataStream::SortMode::Stream)
113	            {
114	                assert(input_stream.has_single_port);
115	
116	                pipeline.addSimpleTransform(
117	                    [&](const Block & header, QueryPipelineBuilder::StreamType stream_type) -> ProcessorPtr
118	                    {
119	                        if (stream_type != QueryPipelineBuilder::StreamType::Main)
120	                            return nullptr;
121	
122	                        return std::make_shared<DistinctSortedTransform>(header, distinct_sort_desc, set_size_limits, limit_hint, columns);
123	                    });
124	                return;
125	            }
126	        }
127	    }
128	
129	    pipeline.addSimpleTransform(
130	        [&](const Block & header, QueryPipelineBuilder::StreamType stream_type) -> ProcessorPtr
131	        {
132	            if (stream_type != QueryPipelineBuilder::StreamType::Main)
133	                return nullptr;
134	
135	            return std::make_shared<DistinctTransform>(header, set_size_limits, limit_hint, columns);
136	        });
137	}
