11	DistinctSortedTransform::DistinctSortedTransform(
12	    Block header_, SortDescription sort_description, const SizeLimits & set_size_limits_, UInt64 limit_hint_, const Names & columns)
13	    : ISimpleTransform(header_, header_, true)
14	    , header(std::move(header_))
15	    , description(std::move(sort_description))
16	    , column_names(columns)
17	    , limit_hint(limit_hint_)
18	    , set_size_limits(set_size_limits_)
19	{
20	    /// pre-calculate column positions to use during chunk transformation
21	    const size_t num_columns = column_names.empty() ? header.columns() : column_names.size();
22	    column_positions.reserve(num_columns);
23	    for (size_t i = 0; i < num_columns; ++i)
24	    {
25	        auto pos = column_names.empty() ? i : header.getPositionByName(column_names[i]);
26	        const auto & col = header.getByPosition(pos).column;
27	        if (col && !isColumnConst(*col))
28	            column_positions.emplace_back(pos);
29	    }
30	}
