32	void DistinctSortedTransform::transform(Chunk & chunk)
33	{
34	        const ColumnRawPtrs column_ptrs(getKeyColumns(chunk));
35	        if (column_ptrs.empty())
36	            return;
37	
38	        ColumnRawPtrs clearing_hint_columns(getClearingColumns(column_ptrs));
39	
40	        if (data.type == ClearableSetVariants::Type::EMPTY)
41	            data.init(ClearableSetVariants::chooseMethod(column_ptrs, key_sizes));
42	
43	        const size_t rows = chunk.getNumRows();
44	        IColumn::Filter filter(rows);
45	
46	        bool has_new_data = false;
47	        switch (data.type)
48	        {
49	            case ClearableSetVariants::Type::EMPTY:
50	                break;
51	    #define M(NAME) \
52	            case ClearableSetVariants::Type::NAME: \
53	                has_new_data = buildFilter(*data.NAME, column_ptrs, clearing_hint_columns, filter, rows, data); \
54	                break;
55	        APPLY_FOR_SET_VARIANTS(M)
56	    #undef M
57	        }
58	
59	        /// Just go to the next block if there isn't any new record in the current one.
60	        if (!has_new_data)
61	        {
62	            chunk.clear();
63	            return;
64	        }
65	
66	        if (!set_size_limits.check(data.getTotalRowCount(), data.getTotalByteCount(), "DISTINCT", ErrorCodes::SET_SIZE_LIMIT_EXCEEDED))
67	        {
68	            stopReading();
69	            chunk.clear();
70	            return;
71	        }
72	
73	        /// Stop reading if we already reached the limit.
74	        if (limit_hint && data.getTotalRowCount() >= limit_hint)
75	            stopReading();
76	
77	        prev_chunk.chunk = std::move(chunk);
78	        prev_chunk.clearing_hint_columns = std::move(clearing_hint_columns);
79	
80	        size_t all_columns = prev_chunk.chunk.getNumColumns();
81	        Chunk res_chunk;
82	        for (size_t i = 0; i < all_columns; ++i)
83	            res_chunk.addColumn(prev_chunk.chunk.getColumns().at(i)->filter(filter, -1));
84	
85	        chunk = std::move(res_chunk);
86	}
