89	template <typename Method>
90	bool DistinctSortedTransform::buildFilter(
91	    Method & method,
92	    const ColumnRawPtrs & columns,
93	    const ColumnRawPtrs & clearing_hint_columns,
94	    IColumn::Filter & filter,
95	    size_t rows,
96	    ClearableSetVariants & variants) const
97	{
98	    typename Method::State state(columns, key_sizes, nullptr);
99	
100	    /// Compare last row of previous block and first row of current block,
101	    /// If rows not equal, we can clear HashSet,
102	    /// If clearing_hint_columns is empty, we CAN'T clear HashSet.
103	    if (!clearing_hint_columns.empty() && !prev_chunk.clearing_hint_columns.empty()
104	        && !rowsEqual(clearing_hint_columns, 0, prev_chunk.clearing_hint_columns, prev_chunk.chunk.getNumRows() - 1))
105	    {
106	        method.data.clear();
107	    }
108	
109	    bool has_new_data = false;
110	    for (size_t i = 0; i < rows; ++i)
111	    {
112	        /// Compare i-th row and i-1-th row,
113	        /// If rows are not equal, we can clear HashSet,
114	        /// If clearing_hint_columns is empty, we CAN'T clear HashSet.
115	        if (i > 0 && !clearing_hint_columns.empty() && !rowsEqual(clearing_hint_columns, i, clearing_hint_columns, i - 1))
116	            method.data.clear();
117	
118	        auto emplace_result = state.emplaceKey(method.data, i, variants.string_pool);
119	
120	        if (emplace_result.isInserted())
121	            has_new_data = true;
122	
123	        /// Emit the record if there is no such key in the current set yet.
124	        /// Skip it otherwise.
125	        filter[i] = emplace_result.isInserted();
126	    }
127	    return has_new_data;
128	}
