130	ColumnRawPtrs DistinctSortedTransform::getKeyColumns(const Chunk & chunk) const
131	{
132	    ColumnRawPtrs column_ptrs;
133	    column_ptrs.reserve(column_positions.size());
134	    for (const auto pos : column_positions)
135	    {
136	        const auto & column = chunk.getColumns()[pos];
137	        column_ptrs.emplace_back(column.get());
138	    }
139	    return column_ptrs;
140	}
