142	ColumnRawPtrs DistinctSortedTransform::getClearingColumns(const ColumnRawPtrs & key_columns) const
143	{
144	    ColumnRawPtrs clearing_hint_columns;
145	    clearing_hint_columns.reserve(description.size());
146	    for (const auto & sort_column_description : description)
147	    {
148	        const auto * sort_column_ptr = header.getByName(sort_column_description.column_name).column.get();
149	        const auto it = std::find(key_columns.cbegin(), key_columns.cend(), sort_column_ptr);
150	        if (it != key_columns.cend()) /// if found in key_columns
151	            clearing_hint_columns.emplace_back(sort_column_ptr);
152	        else
153	            return clearing_hint_columns; /// We will use common prefix of sort description and requested DISTINCT key.
154	    }
155	    return clearing_hint_columns;
156	}
