158	bool DistinctSortedTransform::rowsEqual(const ColumnRawPtrs & lhs, size_t n, const ColumnRawPtrs & rhs, size_t m)
159	{
160	    for (size_t column_index = 0, num_columns = lhs.size(); column_index < num_columns; ++column_index)
161	    {
162	        const auto & lhs_column = *lhs[column_index];
163	        const auto & rhs_column = *rhs[column_index];
164	        if (lhs_column.compareAt(n, m, rhs_column, 0) != 0) /// not equal
165	            return false;
166	    }
167	    return true;
168	}
